//! Semantic equivalence of statement format 3 and witness formats 2/3 with the per-position
//! reference, on the guest's own kernel (PROOF-FMT lane, GUIDANCE §57.9 change **A**).
//!
//! The vectors are `fixtures/proof-format-v3/vectors.json`, generated by the predecessor
//! implementation's Python reference and frozen (that reference decided every one of them;
//! `expected` is its verdict).  Here every vector is decided
//! by *every* kernel path that can take it and the decisions must agree exactly -- not "both
//! reject" but the same `CheckError` value, position attribution included:
//!
//! * format-3 statement + packed witness: `check_batch_ranged(v3, w)` (the optimized path, which
//!   never expands) vs `check_batch_packed(expand_statement(v3), w)` and
//!   `check_batch_packed(parse_statement(v2 bytes), w)` (the reference), plus the byte-level
//!   `verify` boundary on both statements' bytes;
//! * format-2 statement + multiproof witness: `check_batch_multi` vs `check_batch_planned` with the
//!   honest plan (and the Rust `plan_of`), vs `check_batch` on the format-1 witness where one exists;
//! * ill-formed ranges: `parse_statement_v3` and `parse_any_statement` refuse them.
//!
//! The last test pins that this build is sound: the `unsound-*` diagnostic features are off.

use serde::Deserialize;
use veritor_zk_common::{
    check_batch, check_batch_multi, check_batch_packed, check_batch_planned, check_batch_ranged,
    check_openings_packed, check_openings_ranged, expand_statement, gate_set, parse_any_statement,
    parse_multiproof_witness, parse_packed_witness, parse_plan, parse_statement,
    parse_statement_v3, parse_witness, plan_of, verify, CheckError, PositionEntry,
    DIAGNOSTIC_BANNER, UNSOUND, VERDICT_ACCEPT, VERDICT_REJECT,
};

const FILE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../../fixtures/proof-format-v3/vectors.json"
);

#[derive(Deserialize)]
struct Document {
    schema: String,
    vectors: Vec<Vector>,
}

#[derive(Deserialize)]
struct Vector {
    name: String,
    family: String,
    #[serde(default)]
    statement_v3: Option<String>,
    #[serde(default)]
    statement_v2: Option<String>,
    #[serde(default)]
    witness: Option<String>,
    #[serde(default)]
    witness_openings: Option<String>,
    #[serde(default)]
    plan: Option<String>,
    expected: String,
    #[serde(default)]
    words: Option<Vec<Vec<u64>>>,
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn load() -> Vec<Vector> {
    let text = std::fs::read_to_string(FILE)
        .expect("fixtures/proof-format-v3/vectors.json (run the Python suite)");
    let document: Document = serde_json::from_str(&text).unwrap();
    assert_eq!(document.schema, "veritor/proof-format-v3/vectors/v1");
    document.vectors
}

/// The Python verification code the kernel's error must correspond to (phase equivalence).
fn phase_matches(code: &str, error: &CheckError) -> bool {
    match code {
        "INVALID_OPENING" => matches!(error, CheckError::Opening { .. }),
        "MALFORMED_TRANSCRIPT" => matches!(error, CheckError::WitnessShape(_)),
        "RELATION_REJECTED" => matches!(error, CheckError::Relation { .. }),
        "PUBLIC_IO_MISMATCH" => matches!(error, CheckError::PublicInput { .. }),
        "INVALID_VALUE" => matches!(error, CheckError::Value { .. }),
        other => panic!("unknown expected code {other}"),
    }
}

/// Whether a vector's rejection rests on authentication alone (what a diagnostic build skips).
fn authentication_only(expected: &str) -> bool {
    expected == "reject:INVALID_OPENING"
}

fn expect(name: &str, expected: &str, result: &Result<(), CheckError>) {
    if UNSOUND && authentication_only(expected) {
        return; // a diagnostic build does not authenticate; path equality is still asserted by the caller
    }
    match (expected, result) {
        ("accept", Ok(())) => {}
        ("accept", Err(e)) => panic!("{name}: expected accept, got {e:?}"),
        (code, Ok(())) => panic!("{name}: expected {code}, got accept"),
        (code, Err(e)) => {
            let code = code.strip_prefix("reject:").unwrap_or(code);
            assert!(phase_matches(code, e), "{name}: expected {code}, got {e:?}");
        }
    }
}

#[test]
fn every_packed_vector_is_decided_identically_by_the_ranged_and_the_expanded_paths() {
    let mut accepted = 0;
    let mut rejected = 0;
    for v in load()
        .into_iter()
        .filter(|v| v.family == "accept" || v.family == "reject-witness")
    {
        let name = &v.name;
        let bytes3 = hex(v.statement_v3.as_ref().unwrap());
        let bytes2 = hex(v.statement_v2.as_ref().unwrap());
        let v3 = parse_statement_v3(&bytes3).unwrap_or_else(|e| panic!("{name}: v3 parse {e}"));
        let v2 = parse_statement(&bytes2).unwrap_or_else(|e| panic!("{name}: v2 parse {e}"));
        assert!(
            v3.obligations.iter().any(|o| o
                .positions
                .iter()
                .any(|e| matches!(e, PositionEntry::Range(_)))),
            "{name}: has a range"
        );
        // the expansion is the recorded v2 statement, obligation for obligation
        assert_eq!(expand_statement(&v3), v2, "{name}: expand(v3) == v2");
        assert_ne!(
            veritor_zk_common::sha256(&bytes3),
            veritor_zk_common::sha256(&bytes2),
            "{name}: digests differ"
        );
        assert!(
            parse_statement(&bytes3).is_err() && parse_statement_v3(&bytes2).is_err(),
            "{name}: formats are disjoint"
        );
        let witness_bytes = hex(v.witness.as_ref().unwrap());
        let witness = parse_packed_witness(&witness_bytes)
            .unwrap_or_else(|e| panic!("{name}: witness parse {e}"));

        // the three in-memory decisions: exactly equal (same error, same attribution)
        let ranged = check_batch_ranged(&v3, &witness);
        let expanded = check_batch_packed(&expand_statement(&v3), &witness);
        let reference = check_batch_packed(&v2, &witness);
        assert_eq!(ranged, expanded, "{name}: ranged vs expanded");
        assert_eq!(ranged, reference, "{name}: ranged vs recorded v2");
        expect(name, &v.expected, &ranged);

        // the words handed to the relation: same on both passes, and (accept) the recorded oracle
        let set = gate_set(&v2).unwrap();
        let words3 = check_openings_ranged(&v3, &witness, &set);
        let words2 = check_openings_packed(&v2, &witness, &set);
        assert_eq!(words3, words2, "{name}: decoded words");
        if let Some(oracle) = &v.words {
            assert_eq!(
                words3.as_ref().unwrap(),
                oracle,
                "{name}: words vs leaf-byte oracle"
            );
        }

        // the byte-level boundary: same verdict on both statements' bytes, over each one's own digest
        let d3 = verify(&bytes3, &witness_bytes, &[], &[]);
        let d2 = verify(&bytes2, &witness_bytes, &[], &[]);
        assert_eq!(d3.verdict(), d2.verdict(), "{name}: verify verdict");
        if !(UNSOUND && authentication_only(&v.expected)) {
            assert_eq!(
                d3.verdict(),
                v.expected == "accept",
                "{name}: verify vs expected"
            );
        }
        assert_eq!(
            &d3.public_values()[..32],
            &veritor_zk_common::sha256(&bytes3),
            "{name}: v3 digest committed"
        );
        assert_eq!(
            &d2.public_values()[..32],
            &veritor_zk_common::sha256(&bytes2),
            "{name}: v2 digest committed"
        );
        assert_eq!(
            d3.public_values()[32],
            if d3.verdict() {
                VERDICT_ACCEPT
            } else {
                VERDICT_REJECT
            }
        );
        // a format-3 statement takes no plan and no other witness format (never a fallback)
        let plan = plan_of(&v2).ok().map(|p| {
            let mut bytes = veritor_zk_common::PLAN_MAGIC.to_vec();
            for list in [&p.leaf_counts, &p.tree_of, &p.leaf_of] {
                bytes.extend((list.len() as u32).to_be_bytes());
                for x in list {
                    bytes.extend(x.to_be_bytes());
                }
            }
            bytes
        });
        if let Some(plan) = plan {
            assert!(
                !verify(&bytes3, &witness_bytes, &plan, &[]).verdict(),
                "{name}: v3 + plan is refused"
            );
        }
        if v.expected == "accept" {
            accepted += 1;
        } else {
            rejected += 1;
        }
    }
    assert!(
        accepted >= 7 && rejected >= 14,
        "accept {accepted}, reject {rejected}"
    );
    eprintln!("packed vectors: {accepted} accepted, {rejected} rejected, all paths agree");
}

#[test]
fn every_multiproof_vector_is_decided_identically_by_the_shared_planned_and_per_opening_paths() {
    let mut n = 0;
    for v in load().into_iter().filter(|v| v.family == "multiproof") {
        let name = &v.name;
        let bytes2 = hex(v.statement_v2.as_ref().unwrap());
        let statement = parse_statement(&bytes2).unwrap_or_else(|e| panic!("{name}: parse {e}"));
        let witness_bytes = hex(v.witness.as_ref().unwrap());
        let multi = parse_multiproof_witness(&witness_bytes)
            .unwrap_or_else(|e| panic!("{name}: witness {e}"));
        let plan_bytes = hex(v.plan.as_ref().unwrap());
        let plan = parse_plan(&plan_bytes).unwrap();
        // the Python plan is the Rust plan
        assert_eq!(
            plan,
            plan_of(&statement).unwrap(),
            "{name}: plan_of == encode_plan"
        );
        let shared = check_batch_multi(&statement, &multi);
        let planned = check_batch_planned(&statement, &multi, &plan);
        assert_eq!(shared, planned, "{name}: multi vs planned");
        expect(name, &v.expected, &shared);
        if let Some(openings) = &v.witness_openings {
            let opened = parse_witness(&hex(openings)).unwrap();
            let per_opening = check_batch(&statement, &opened);
            // same decision and same phase; the per-opening pass attributes to (obligation, position)
            // while the shared pass attributes to the first position that defined the leaf, so the
            // full error value may differ in `position` only
            assert_eq!(
                per_opening.is_ok(),
                shared.is_ok(),
                "{name}: per-opening vs shared"
            );
            if let (Err(a), Err(b)) = (&per_opening, &shared) {
                assert_eq!(
                    std::mem::discriminant(a),
                    std::mem::discriminant(b),
                    "{name}: {a:?} vs {b:?}"
                );
            }
            let d1 = verify(&bytes2, &hex(openings), &[], &[]);
            if !(UNSOUND && authentication_only(&v.expected)) {
                assert_eq!(
                    d1.verdict(),
                    v.expected == "accept",
                    "{name}: verify format 1"
                );
            }
        }
        let d2 = verify(&bytes2, &witness_bytes, &[], &[]);
        let dp = verify(&bytes2, &witness_bytes, &plan_bytes, &[]);
        assert_eq!(
            d2.verdict(),
            dp.verdict(),
            "{name}: verify format 2 vs format 2 + plan"
        );
        if !(UNSOUND && authentication_only(&v.expected)) {
            assert_eq!(
                d2.verdict(),
                v.expected == "accept",
                "{name}: verify format 2"
            );
        }
        n += 1;
    }
    assert!(n >= 14, "{n} multiproof vectors");
}

#[test]
fn every_parse_reject_vector_is_refused_by_the_parser() {
    let mut n = 0;
    for v in load().into_iter().filter(|v| v.family == "reject-parse") {
        let bytes = hex(v.statement_v3.as_ref().unwrap());
        let error = parse_statement_v3(&bytes).expect_err(&v.name);
        assert!(parse_any_statement(&bytes).is_err(), "{}", v.name);
        // the byte boundary rejects too, over the digest of the bytes as given
        let d = verify(&bytes, &[], &[], &[]);
        assert!(!d.verdict(), "{}: {error}", v.name);
        assert_eq!(&d.public_values()[..32], &veritor_zk_common::sha256(&bytes));
        eprintln!("{}: {error}", v.name);
        n += 1;
    }
    assert!(n >= 12, "{n} parse-reject vectors");
}

/// A sound build: neither diagnostic feature is on.  `UNSOUND` is a `const` of the crate computed
/// from `cfg!`, so this fails at runtime in *any* build that turned one on -- in particular in a
/// default build should an `unsound-*` feature ever be made a default.  (A `compile_error!` would
/// do the same but would also stop the documented diagnostic run `cargo test --features unsound-*`
/// from compiling the crate's other test targets, which `vectors.rs` adapts to; a failing test
/// names the problem just as loudly.)
#[test]
#[allow(clippy::assertions_on_constants)] // the point: these are build-time constants, pinned at test time
fn this_build_is_sound() {
    assert!(
        !UNSOUND,
        "an unsound-* diagnostic feature is on ({:?}): this build's verdicts are not results",
        DIAGNOSTIC_BANNER
    );
    assert!(DIAGNOSTIC_BANNER.is_none());
    assert_eq!((VERDICT_ACCEPT, VERDICT_REJECT), (1, 0));
    assert!(!cfg!(feature = "unsound-skip-authentication"));
    assert!(!cfg!(feature = "unsound-skip-path-fold"));
}
